/* HEXA BATTLEGROUNDS upgrade — PART 31 OF 31. Only for databases that already ran setup part-01…; Run in order. Safe to re-run. */ insert into mission_templates(id, family, kind, title, category, difficulty, tags, objective, clues, parts, relay, attempts, time_limit, hint, explanation, points, coins, status) values ('airdrop-fruit-12', 'fruit', 'airdrop', 'Fruit Slash', 'game', 1, array['any']::text[], 'Scout plays Fruit Slash: slicing a fruit reveals its hidden digit. Intel knows which fruits make the vault code. Decoder knows how to scramble it.', '{"scout":{"title":"Fruit Slash","body":"Swipe across flying fruit to slice it. Each fruit type always hides the same digit. Avoid the 💣 (it just costs you time). Call out what you find.","game":{"type":"fruit","fruits":[{"f":"🍌","d":0},{"f":"🍍","d":1},{"f":"🍇","d":9},{"f":"🍎","d":3},{"f":"🍒","d":2},{"f":"🥝","d":8}],"bomb":true,"seconds":30}},"intel":{"title":"Vault order","body":"🍌   🍒   🍇   🥝\n(Banana, Cherry, Grapes, Kiwi)","big":true},"decoder":{"title":"Scramble rule","body":"Subtract each digit from 9."}}'::jsonb, '[{"label":"4-digit vault code","accept":["9701"]}]'::jsonb, false, 3, 150, 'Scout: shout every fruit and digit you slice. Intel: tell everyone which four fruits matter, in order.', '🍌=0 🍒=2 🍇=9 🥝=8 → 9 minus each digit → 9701', null, 25, 'published'), ('airdrop-fruit-13', 'fruit', 'airdrop', 'Fruit Slash', 'game', 1, array['any']::text[], 'Scout plays Fruit Slash: slicing a fruit reveals its hidden digit. Intel knows which fruits make the vault code. Decoder knows how to scramble it.', '{"scout":{"title":"Fruit Slash","body":"Swipe across flying fruit to slice it. Each fruit type always hides the same digit. Avoid the 💣 (it just costs you time). Call out what you find.","game":{"type":"fruit","fruits":[{"f":"🍊","d":2},{"f":"🍉","d":7},{"f":"🥭","d":9},{"f":"🍍","d":5},{"f":"🥝","d":0},{"f":"🍌","d":3}],"bomb":true,"seconds":30}},"intel":{"title":"Vault order","body":"🥝   🍊   🍉   🍌\n(Kiwi, Orange, Watermelon, Banana)","big":true},"decoder":{"title":"Scramble rule","body":"Add 3 to every digit and keep only the last digit (8 → 1)."}}'::jsonb, '[{"label":"4-digit vault code","accept":["3506"]}]'::jsonb, false, 3, 150, 'Scout: shout every fruit and digit you slice. Intel: tell everyone which four fruits matter, in order.', '🥝=0 🍊=2 🍉=7 🍌=3 → +3 to each digit, last digit only → 3506', null, 25, 'published') on conflict (id) do update set family = excluded.family, kind = excluded.kind, title = excluded.title, category = excluded.category, difficulty = excluded.difficulty, tags = excluded.tags, objective = excluded.objective, clues = excluded.clues, parts = excluded.parts, relay = excluded.relay, attempts = excluded.attempts, time_limit = excluded.time_limit, hint = excluded.hint, explanation = excluded.explanation, points = excluded.points, coins = excluded.coins, status = excluded.status, version = case when mission_templates.clues is distinct from excluded.clues or mission_templates.parts is distinct from excluded.parts then mission_templates.version + 1 else mission_templates.version end, updated_at = now();
